function R = BoutAR1Noise(bouts, opts)
%BOUTAR1NOISE  Fit x(t+1) = A + B*x(t) + eps in bout space and test its assumptions.
%
%   R = BoutAR1Noise(bouts, Xmin=300)
%   R = BoutAR1Noise(bouts, Xmin=300, Strata=st, NumSurrogates=1000, ...)
%
% Answers, per fly and one bout type at a time, the question "can the bouts
% be generated by a linear AR(1) in bout space, and what does its noise look
% like?" -- directly in seconds, with no transform.
%
% MODEL. Ordinary least squares of x(t+1) on x(t), over all consecutive pairs
% within a block (a pair never spans two blocks):
%       x(t+1) = A + B*x(t) + eps(t).
% B equals the lag-1 Pearson correlation of the pairs (up to the two ends of
% each block), and eps are the residuals.
%
% WHAT IS CHECKED (each against the same statistic on surrogate sequences):
%   B           linear memory. Null: no memory.
%   Hetero      Spearman correlation of |eps| with x(t). The linear AR(1)
%               with iid noise says the spread of eps does not depend on the
%               previous bout: Hetero ~ 0. A transformed-Gaussian AR(1) (the
%               copula model) makes the spread grow with x(t). MEASURED in
%               test_BoutAR1Noise.
%   ShapeKS     Kolmogorov-Smirnov distance between this fly's eps and the
%               eps the SAME bouts give once their order is randomised (pooled
%               over surrogates). Small = "eps is what the bout distribution
%               gives with no dynamics"; its p-value asks whether order changes
%               the noise's shape.
%   BelowHalfB  EAR(1) check. The only linear AR(1) with iid noise that keeps
%               exponential bouts above Xmin (Gaver & Lewis 1980; Lawrance &
%               Lewis 1980) has y(t+1) >= B*y(t), y = x - Xmin, always, with
%               EQUALITY on a fraction B of the steps. Testing y(t+1) < Bhat*y(t)
%               with the fitted Bhat is useless: those equality steps flip
%               whenever Bhat exceeds B at all (MEASURED: true B 0.4, Bhat
%               0.452 gave 41% "violations"). BelowHalfB is the fraction of
%               pairs with y(t+1) < (Bhat/2)*y(t), which EAR(1) puts at 0 even
%               for a loose Bhat. NaN when Bhat <= 0. DESCRIPTIVE: when Bhat is
%               near 0 the threshold is near 0 and independent bouts give
%               almost no pairs below it either, so it cannot then tell EAR(1)
%               from no dynamics.
%   REGENERATION ("can the model generate the observed bouts?"). 200
%               sequences per fly from the fitted A, B with eps drawn with
%               replacement from the fly's own residuals, each block started
%               at its observed first bout, same lengths. NOTHING IS CLIPPED:
%                 GenBelowXmin  fraction of generated bouts below Xmin (the
%                               protocol floor: 300 s sleep, 2 s wake). A
%                               model that generates the data puts ~0 there.
%                 GenMinBout    the smallest generated bout.
%                 GenKS         mean KS distance, generated vs observed bouts;
%                 GenKS_Ref     the same for a bootstrap resample of the
%                               observed bouts -- the KS from sampling alone.
%               Additive iid noise has nothing that keeps x(t+1) >= Xmin, so
%               GenBelowXmin > 0 is expected whenever B is not ~0.
%   Descriptive: residual moment skewness, Bowley skewness (mid-quantiles),
%   SD, and the same three for the no-dynamics residuals (surrogate means).
%
% NULLS
%   'shuffle'   (default) random permutation within each block.
%   'strata'    when Strata is given (same shape as bouts, one label per bout,
%               e.g. floor of onset ZT): permutation only among positions
%               with the same label, across the fly's blocks, so a light:dark
%               profile is in the null (see BoutIrreversibility for why).
%   Both are sample-size matched. P-values are two-sided Monte Carlo values
%   with the +1 correction, except ShapeKS (one-sided: larger = more
%   different).
%   GROUP: mean over flies of B and Hetero against the mean of the flies' r-th
%   surrogates (valid for the shuffle null; with strata the group MEAN can be
%   biased, as BoutIrreversibility measured -- use the count), plus the COUNT
%   of flies with p < 0.05 against Binomial(NFlies, 0.05) for B, Hetero and
%   ShapeKS.
%
% INPUT
%   bouts   numeric vector (one fly), matrix (one fly per row, trailing NaN
%           padding), or cell per fly of vectors or cell arrays of blocks --
%           the same forms as BoutIrreversibility.
% OPTIONS
%   Xmin           REQUIRED. The protocol's shortest bout (300 for sleep,
%                  2 for 1-s-bridged wake), in the bouts' units.
%   NumSurrogates  Default 1000.
%   Strata         Default [] (shuffle null).
%   Seed           Private RandStream ('mrg32k3a', substream = fly index).
%                  Default 1.
%   MinPairs       Flies with fewer pairs get NaN. Default 20.
%   FlyNames       Default "fly1", ...
%   ReturnResiduals true to return each fly's pairs and residuals.
%
% OUTPUT  struct R
%   PerFly   table: Fly, NPairs, MeanBout, A, B, B_P, Hetero, Hetero_P,
%            ShapeKS, ShapeKS_P, BelowHalfB, BelowHalfB_NullMean, ResidSD,
%            ResidSD_Null, ResidSkew, ResidSkew_Null, ResidBowley,
%            ResidBowley_Null, GenBelowXmin, GenMinBout, GenKS, GenKS_Ref.
%   Group    table: NFlies, Null; for B, Hetero: Mean, Mean_P, NSig, CountP;
%            for ShapeKS: NSig, CountP; median BelowHalfB and its null;
%            median GenBelowXmin, GenKS, GenKS_Ref.
%
% LIGHT:DARK DATA: fit each phase separately by calling once per phase with
% that phase's blocks (each 12-h light or dark period of each day one block,
% so no pair spans lights-on/off), and Strata = 1-h ZT bins for the trend
% within a phase.
%   Residuals (ReturnResiduals) cell per fly: [x(t) x(t+1) eps].
%   Settings
%
% CAVEATS
%   - Least squares on exponential-like data: B and A are dominated by the
%     long bouts. Fine for the questions above; not an efficient estimator.
%   - eps overlap in time (each bout is a response once and a predictor
%     once), so no iid formula is used for any p-value.
%   - A linear AR(1) can be a poor model even when B is "significant"; that
%     is what Hetero and BelowHalfB are for.
%
% REFERENCES
%   Gaver DP, Lewis PAW (1980) First-order autoregressive gamma sequences
%     and point processes. Adv Appl Prob 12:727-745.
%   Lawrance AJ, Lewis PAW (1980) The exponential autoregressive-moving
%     average EARMA(p,q) process. J R Stat Soc B 42:150-161.
%   Lawrance AJ (1991) Directionality and reversibility in time series.
%     Int Stat Rev 59:67-79.
%
% MEASURED CALIBRATION (test_BoutAR1Noise, MATLAB R2026a, 2026-11-05; 200
% simulated flies of 150 bouts per row, 199 surrogates; rejection at 0.05):
%                                         B      Hetero   ShapeKS
%   iid exponential, shuffle null       0.030    0.045    0.060
%   EAR(1) B 0.3 (linear, flat spread)  0.940    0.085    1.000
%   Gaussian-copula AR(1) phi 0.5       1.000    0.695    1.000
%   LD-like, NO memory, shuffle null    0.465    0.305    0.455  (median B 0.18
%                                                         from the profile alone)
%   LD-like, NO memory, strata null     0.030    0.040    0.050
% So Hetero separates the linear model (0.085) from the transformed one
% (0.695); ShapeKS fires whenever there is memory (memory narrows eps), so
% it means "the dynamics change eps", not "eps has an exotic shape"; and in
% LD the profile alone fakes B unless the strata null is used. The LD rows
% were simulated on whole records with 1-h strata, not per phase.
% Regeneration (n = 400): below 300 s, iid 0.014 (Bhat -0.044), EAR(1)
% 0.000 (Bhat 0.357: its non-negative innovations keep the floor), copula
% AR(1) 0.086 (Bhat 0.392); wake-like 60-s bouts below 2 s: 0.051 with Bhat
% -0.110 -- a negative B alone breaks the floor.
%
% Needs no toolbox.
%
% CHANGE LOG
%   2026-11-05  First version.

arguments
    bouts
    opts.Xmin (1,1) double {mustBeFinite}
    opts.NumSurrogates (1,1) double {mustBeInteger, mustBePositive} = 1000
    opts.Strata = []
    opts.Seed (1,1) double {mustBeInteger, mustBeNonnegative} = 1
    opts.MinPairs (1,1) double {mustBeInteger, mustBePositive} = 20
    opts.FlyNames string = string.empty
    opts.ReturnResiduals (1,1) logical = false
end
if ~isfield(opts, 'Xmin')
    error('BoutAR1Noise:Xmin', 'Xmin is required (e.g. 300 for sleep bouts).');
end

flies = to_flies(bouts);
nF = numel(flies);
hasStrata = ~isempty(opts.Strata);
if hasStrata
    strata = to_flies(opts.Strata);
    ok = numel(strata) == nF;
    for f = 1:nF
        ok = ok && numel(strata{f}) == numel(flies{f}) && ...
            all(cellfun(@numel, strata{f}) == cellfun(@numel, flies{f}));
    end
    if ~ok
        error('BoutAR1Noise:Strata', 'Strata do not match bouts block for block.');
    end
end
if isempty(opts.FlyNames)
    names = "fly" + string(1:nF);
else
    names = opts.FlyNames(:).';
    if numel(names) ~= nF, error('BoutAR1Noise:FlyNames', 'Wrong number of FlyNames.'); end
end
Rn = opts.NumSurrogates;

fields = ["NPairs","MeanBout","A","B","B_P","Hetero","Hetero_P","ShapeKS","ShapeKS_P", ...
    "BelowHalfB","BelowHalfB_NullMean","ResidSD","ResidSD_Null","ResidSkew","ResidSkew_Null", ...
    "ResidBowley","ResidBowley_Null","GenBelowXmin","GenMinBout","GenKS","GenKS_Ref"];
V = NaN(nF, numel(fields));
nullB = NaN(nF, Rn);
nullH = NaN(nF, Rn);
resid = cell(nF, 1);

for f = 1:nF
    blocks = flies{f};
    xAll = vertcat(blocks{:});
    [s, a, c, e] = fit_stats(blocks, opts.Xmin);
    if s.n < opts.MinPairs, continue, end
    resid{f} = [a c e];
    rs = RandStream('mrg32k3a', 'Seed', opts.Seed);
    rs.Substream = f;
    blen = cellfun(@numel, blocks);
    if hasStrata
        [~, ~, g] = unique(vertcat(strata{f}{:}));
        groups = accumarray(g, (1:numel(g)).', [], @(v) {v});
        groups = groups(cellfun(@numel, groups) > 1);
    end
    sur = struct('B', NaN(Rn, 1), 'H', NaN(Rn, 1), 'neg', NaN(Rn, 1), ...
        'sd', NaN(Rn, 1), 'sk', NaN(Rn, 1), 'bw', NaN(Rn, 1));
    eSur = cell(Rn, 1);
    for r = 1:Rn
        if hasStrata
            y = xAll;
            for k = 1:numel(groups)
                ix = groups{k};
                y(ix) = xAll(ix(randperm(rs, numel(ix))));
            end
        else
            y = xAll;
            o = 0;
            for b = 1:numel(blocks)
                ix = o + (1:blen(b));
                y(ix) = xAll(ix(randperm(rs, blen(b))));
                o = o + blen(b);
            end
        end
        sb = mat2cell(y, blen, 1).';
        [ss, ~, ~, es] = fit_stats(sb, opts.Xmin);
        sur.B(r) = ss.B; sur.H(r) = ss.hetero; sur.neg(r) = ss.neg;
        sur.sd(r) = ss.sd; sur.sk(r) = ss.skew; sur.bw(r) = ss.bowley;
        eSur{r} = es;
    end
    % ShapeKS: this fly's eps against the pooled no-dynamics eps; its null
    % is each surrogate's eps against the pool without that surrogate. To
    % keep the cost bounded, the pool is built from at most 200 surrogates.
    nPool = min(Rn, 200);
    pool = sort(vertcat(eSur{1:nPool}));
    ksObs = ks_dist(e, pool);
    ksNull = NaN(nPool, 1);
    for r = 1:nPool
        others = sort(vertcat(eSur{[1:r-1, r+1:nPool]}));
        ksNull(r) = ks_dist(eSur{r}, others);
    end
    V(f, :) = [s.n, mean(xAll), s.A, s.B, mc_p(s.B, sur.B), s.hetero, mc_p(s.hetero, sur.H), ...
        ksObs, (1 + sum(ksNull >= ksObs)) / (nPool + 1), ...
        s.neg, mean(sur.neg, 'omitnan'), s.sd, mean(sur.sd, 'omitnan'), ...
        s.skew, mean(sur.sk, 'omitnan'), s.bowley, mean(sur.bw, 'omitnan'), ...
        regenerate(blocks, s.A, s.B, e, opts.Xmin, opts.Seed, f)];
    nullB(f, :) = sur.B;
    nullH(f, :) = sur.H;
end

T = array2table(V, 'VariableNames', cellstr(fields));
T = addvars(T, names(:), 'Before', 1, 'NewVariableNames', 'Fly');
R.PerFly = T;

in = isfinite(T.B);
G = table(sum(in), 'VariableNames', {'NFlies'});
G.Null = string(ternary(hasStrata, "strata", "shuffle"));
for nm = ["B","Hetero"]
    o = T.(nm)(in);
    if nm == "B", nd = nullB(in, :); else, nd = nullH(in, :); end
    G.(nm + "_Mean") = mean(o);
    G.(nm + "_Mean_P") = mc_p(mean(o), mean(nd, 1, 'omitnan').');
end
for nm = ["B","Hetero","ShapeKS"]
    p = T.(nm + "_P")(in);
    G.(nm + "_NSig") = sum(p < 0.05);
    G.(nm + "_CountP") = binom_upper(sum(p < 0.05), numel(p), 0.05);
end
G.BelowHalfB_Median = median(T.BelowHalfB(in), 'omitnan');
G.BelowHalfB_NullMedian = median(T.BelowHalfB_NullMean(in), 'omitnan');
G.GenBelowXmin_Median = median(T.GenBelowXmin(in));
G.GenKS_Median = median(T.GenKS(in));
G.GenKS_Ref_Median = median(T.GenKS_Ref(in));
R.Group = G;
if opts.ReturnResiduals, R.Residuals = resid; end
R.Settings = opts;
R.Settings.FlyNames = names;
R.Settings.Version = '2026-11-05';
end

% =====================================================================
function [s, a, c, e] = fit_stats(blocks, xmin)
a = cell(numel(blocks), 1);
c = a;
for b = 1:numel(blocks)
    x = blocks{b};
    if numel(x) > 1
        a{b} = x(1:end-1);
        c{b} = x(2:end);
    end
end
a = vertcat(a{:});
c = vertcat(c{:});
s.n = numel(a);
s.A = NaN; s.B = NaN; s.hetero = NaN; s.neg = NaN; s.sd = NaN; s.skew = NaN; s.bowley = NaN;
e = NaN(size(a));
if s.n < 3 || var(a) == 0, return, end
ac = a - mean(a);
s.B = sum(ac .* (c - mean(c))) / sum(ac.^2);
s.A = mean(c) - s.B * mean(a);
e = c - s.A - s.B * a;
s.hetero = spearman(abs(e), a);
if s.B > 0, s.neg = mean((c - xmin) < (s.B / 2) * (a - xmin)); end
ec = e - mean(e);
s.sd = sqrt(mean(ec.^2));
if s.sd > 0, s.skew = mean(ec.^3) / s.sd^3; end
s.bowley = bowley_mid(e);
end

function d = ks_dist(x, ysorted)
% Two-sample Kolmogorov-Smirnov distance; ysorted must be sorted.
x = sort(x(:));
z = unique([x; ysorted]);
Fx = count_le(x, z) / numel(x);
Fy = count_le(ysorted, z) / numel(ysorted);
d = max(abs(Fx - Fy));
end

function k = count_le(v, z)
% Number of elements of v that are <= each z. histcounts puts z in bin m
% when edges(m) <= z < edges(m+1); with edges [-Inf; u; Inf] over the
% distinct values u of v, bin m means u(m-1) <= z < u(m), so the count is
% the cumulative count of u up to m-1.
[u, ~, j] = unique(v(:));
cnt = cumsum(accumarray(j, 1));
[~, ~, bin] = histcounts(z(:), [-Inf; u; Inf]);
k = zeros(numel(z), 1);
k(bin > 1) = cnt(bin(bin > 1) - 1);
end

function r = spearman(a, c)
ra = tied_rank(a); rc = tied_rank(c);
ra = ra - mean(ra); rc = rc - mean(rc);
den = sqrt(sum(ra.^2) * sum(rc.^2));
if den > 0, r = sum(ra .* rc) / den; else, r = NaN; end
end

function r = tied_rank(v)
[~, ~, j] = unique(v);
cnt = accumarray(j, 1);
cum = cumsum(cnt);
avg = cum - (cnt - 1) / 2;
r = avg(j);
end

function b = bowley_mid(x)
x = sort(x(:));
n = numel(x);
[u, ~, j] = unique(x);
b = NaN;
if numel(u) < 2, return, end
c  = accumarray(j, 1);
Fm = (cumsum(c) - c/2) / n;
P  = [0.25 0.5 0.75];
q  = interp1(Fm, u, P, 'linear');
q(P < Fm(1))   = u(1);
q(P > Fm(end)) = u(end);
d = q(3) - q(1);
if d > 0, b = (q(3) + q(1) - 2*q(2)) / d; end
end

function p = mc_p(o, null)
null = null(isfinite(null));
if ~isfinite(o) || isempty(null), p = NaN; return, end
p = min(1, 2 * min(1 + sum(null >= o), 1 + sum(null <= o)) / (numel(null) + 1));
end

function p = binom_upper(k, n, q)
if n == 0, p = NaN; return, end
j = k:n;
lp = gammaln(n + 1) - gammaln(j + 1) - gammaln(n - j + 1) + j*log(q) + (n - j)*log1p(-q);
p = min(1, sum(exp(lp)));
end

function v = ternary(c, a, b)
if c, v = a; else, v = b; end
end

function flies = to_flies(bouts)
% Same input forms as BoutIrreversibility.
if isnumeric(bouts)
    if isvector(bouts)
        flies = {{double(bouts(:))}};
    else
        flies = cell(size(bouts, 1), 1);
        for i = 1:size(bouts, 1)
            row = double(bouts(i, :));
            last = find(~isnan(row), 1, 'last');
            if isempty(last), last = 0; end
            flies{i} = {check(row(1:last).', i)};
        end
    end
elseif iscell(bouts)
    flies = cell(numel(bouts), 1);
    for i = 1:numel(bouts)
        e = bouts{i};
        if isnumeric(e)
            flies{i} = {check(double(e(:)), i)};
        elseif iscell(e)
            flies{i} = cellfun(@(b) check(double(b(:)), i), e(:).', 'UniformOutput', false);
        else
            error('BoutAR1Noise:Input', 'Fly %d is neither numeric nor a cell of blocks.', i);
        end
    end
else
    error('BoutAR1Noise:Input', 'bouts must be numeric or a cell array.');
end
end

function x = check(x, i)
if any(~isfinite(x))
    error('BoutAR1Noise:NonFinite', 'Fly %d has a NaN or Inf inside a block.', i);
end
end

function g = regenerate(blocks, A, B, e, xmin, seed, f)
% Regenerate the fly from its own fitted model: each block starts at its
% observed first bout, then x(t+1) = A + B*x(t) + eps*, eps* drawn with
% replacement from the fly's own residuals (residual bootstrap), for the
% block's own length; 200 sequences. Nothing is clipped: a generated bout
% below Xmin is COUNTED, because a model that can generate the data must
% respect the protocol floor (300 s sleep, 2 s wake) on its own.
% Returns [fraction of generated bouts below Xmin, smallest generated bout,
% mean KS distance generated vs observed bouts, mean KS distance of a
% same-size bootstrap resample of the observed bouts vs the observed bouts
% (the KS expected from sampling alone)].
rs = RandStream('mrg32k3a', 'Seed', seed);
rs.Substream = 2e6 + f;
nRep = 200;
obs = sort(vertcat(blocks{:}));
n = numel(obs);
below = 0; total = 0; gmin = Inf; ks = NaN(nRep, 1); ksRef = ks;
for r = 1:nRep
    gen = cell(numel(blocks), 1);
    for b = 1:numel(blocks)
        x = blocks{b};
        y = zeros(numel(x), 1);
        y(1) = x(1);
        for t = 2:numel(x)
            y(t) = A + B * y(t-1) + e(randi(rs, numel(e)));
        end
        gen{b} = y(2:end);
    end
    gv = vertcat(gen{:});
    below = below + sum(gv < xmin);
    total = total + numel(gv);
    gmin = min(gmin, min(gv));
    ks(r) = ks_dist(gv, obs);
    ksRef(r) = ks_dist(obs(randi(rs, n, n, 1)), obs);
end
g = [below / total, gmin, mean(ks), mean(ksRef)];
end
